              variant="outlined"
              sx={{
                height: "100%",
                display: "flex",
                flexDirection: "column",
                position: "relative",
                borderWidth: isActive ? 2 : 1,
                borderColor: isActive ? "primary.main" : "divider"
              }}
            >
              {isActive && (
                <Chip
                  label="Active"
                  color="primary"
                  size="small"
                  sx={{
                    position: "absolute",
                    top: 8,
                    right: 8
                  }}
                />
              )}
