                <Typography variant="caption" color="text.secondary" sx={{ display: "block", mb: 2 }}>
                  {theme.fontFamily.split(",")[0].replace(/'/g, "")}
                </Typography>
                <Stack direction="row" spacing={0.5} flexWrap="wrap" useFlexGap>
                  {Object.entries(theme.colors)
                    .slice(0, 8)
                    .map(([key, color]) => (
