                        key={key}
                        sx={{
                          width: 24,
                          height: 24,
                          bgcolor: color,
                          border: "1px solid",
                          borderColor: "divider",
                          borderRadius: 0.5
                        }}
                        title={key}
                      />
                    ))}
                </Stack>
              </CardContent>
              <CardActions>
                {!isActive && (
                  <Button size="small" onClick={() => onActivate(theme.id)}>
                    Activate
